<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\WebAuthn\Application\Usecase\FinishRegistration;

use DateTimeImmutable;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnCredential;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Exception\WebAuthnException;
use Civi\Lughauth\Features\OAuth\WebAuthn\Infrastructure\Service\WebAuthnVerifier;
use Civi\Lughauth\Shared\Exception\NotFoundException;

/**
 * Application use case that completes the WebAuthn credential registration ceremony.
 *
 * Validates the pending challenge (existence, expiry, and correct type "register"),
 * confirms the user referenced by the challenge still exists in the system, and
 * delegates the cryptographic attestation verification to WebAuthnVerifier. On
 * success, a new WebAuthnCredential is persisted with the extracted public key,
 * credential ID, sign count, AAGUID, and optional transport hints. An optional
 * human-readable device name may be supplied by the client to help the user manage
 * their registered passkeys. After this call returns, the user may authenticate
 * using the newly registered passkey through the authentication ceremony.
 */
final class FinishRegistrationUsecase
{
    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly UserReadGateway $users,
        private readonly WebAuthnChallengeGateway $challengeGateway,
        private readonly WebAuthnCredentialGateway $credentialGateway,
        private readonly WebAuthnVerifier $verifier,
    ) {
    }

    /**
     * Verifies the attestation response and persists the new passkey credential.
     * Throws WebAuthnException for any cryptographic or protocol violation, and
     * NotFoundException if the tenant or user referenced in the challenge no longer exists.
     */
    public function finish(
        string $challengeId,
        string $tenantName,
        array $clientCredential,
        string $origin,
        string $rpId,
        ?string $deviceName = null,
    ): void {
        $tenant = $this->tenants->findOneByName($tenantName);
        if (!$tenant) {
            throw new NotFoundException('tenant ' . $tenantName);
        }
        $tenantId = $tenant->uid() ?? $tenantName;

        $challenge = $this->challengeGateway->findById($challengeId, $tenantId);
        if (!$challenge) {
            throw WebAuthnException::challengeNotFound();
        }
        if ($challenge->isExpired()) {
            throw WebAuthnException::challengeExpired();
        }
        if ($challenge->type !== 'register') {
            throw WebAuthnException::verificationFailed('wrong challenge type');
        }

        $userUid = $challenge->userUid ?? '';
        $user = $this->users->findOneByUid($userUid);
        if (!$user) {
            throw new NotFoundException('user ' . $userUid);
        }

        $result = $this->verifier->verifyRegistration($clientCredential, $challenge->challenge, $origin, $rpId);

        $this->credentialGateway->store(new WebAuthnCredential(
            uid: Uuid::uuid4()->toString(),
            tenantId: $tenantId,
            userUid: $userUid,
            username: $user->getEmail() ?? $user->getName() ?? $userUid,
            credentialId: $result['credentialId'],
            publicKey: $result['publicKey'],
            signCount: $result['signCount'],
            aaguid: $result['aaguid'] ?? null,
            deviceName: $deviceName,
            transports: $result['transports'] ?? null,
            createdAt: new DateTimeImmutable(),
            lastUsedAt: null,
            enabled: true,
        ));
    }
}
